CREATE TABLE cmdb_ire_sources (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, source_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, name VARCHAR(160) NOT NULL, source_type ENUM('MANUAL','CSV','DISCOVERY','INTEGRATION') NOT NULL, owner_id BIGINT UNSIGNED NULL, scope_key VARCHAR(255) NOT NULL DEFAULT '', connection_ref VARCHAR(200) NULL, source_instance_id VARCHAR(255) NULL, state ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE', priority SMALLINT UNSIGNED NOT NULL DEFAULT 100, is_system BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT UNSIGNED NOT NULL DEFAULT 1, last_successful_read_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE KEY cmdb_ire_source_key(tenant_id,source_key), UNIQUE KEY cmdb_ire_source_tenant_id(tenant_id,id), KEY cmdb_ire_source_state(tenant_id,state,id), CONSTRAINT cmdb_ire_source_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_source_owner FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
